			if(bit(mutedTracks, track) != 0.0) continue;
			List d = trackData(activePattern, track);
			double tlen = d[0.0];
			double curStep = stepIndex[track];
			double nxtStep = imod(curStep + 1.0, tlen);
			double prvStep = tlen - 1.0;
			if(curStep != 0.0) prvStep = curStep - 1.0;
	
			double currentActive = bit(shiftFlamPattern(d, track, curStep, 1.0), 23.0 - idx);
			double nextActive = bit(shiftFlamPattern(d, track, nxtStep, 2.0), 23.0 - idx);
